WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/36.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/36.0/apex.js")} 

try{ 
var excptioncommnts = prompt("Please enter your comments", ""); 
var dys = prompt("No. of days unit should be blocked for",); 
var noofdays = parseInt(dys); 

if(excptioncommnts === "" || dys === ""){ 
alert('Please make sure to enter comments and no. of days'); 
} 

else if (Number(dys)){ 
excptioncommnts = excptioncommnts.substring(0,254); 
var result = sforce.apex.execute('SendtoApproval','inventoryBlockApproval',{objID: "{!Inventory__c.Id}",cmments: excptioncommnts,blockedtill : noofdays}); 
alert(result); 
location.reload(); 
} 

else{ 
alert('Please provide a valid value for no. of days'); 
} 

} 
catch(err){ 
txt="There was an error on this page.\n\n"; 
txt+="Error description: " + err.description + "\n\n"; 
txt+="Click OK to continue.\n\n"; 
alert(txt); 
}
